public class Main {
    static volatile boolean stop = false;
    static volatile long ticks = 0L;
    static boolean plainFlag = false;
    static final Object LOCK = new Object();

    public static void main(String[] args) throws Exception {
        Thread worker = new Thread(() -> { while (!stop) { ticks++; } }, "worker");
        worker.start();
        Thread.sleep(200L);
        stop = true;
        worker.join(3000L);
        System.out.println("volatile flag stopped worker : " + !worker.isAlive());
        System.out.println("worker final state           : " + worker.getState().name());
        System.out.println("worker made progress ticks>0 : " + (ticks > 0L));

        Thread plainWorker = new Thread(() -> {
            while (true) {
                boolean seen;
                synchronized (LOCK) { seen = plainFlag; }
                if (seen) break;
            }
        }, "plain-worker");
        plainWorker.start();
        Thread.sleep(100L);
        synchronized (LOCK) { plainFlag = true; }
        plainWorker.join(3000L);
        System.out.println("synchronized publish worked  : " + !plainWorker.isAlive());
    }
}
